#!/usr/bin/env python3
"""Generate the offline CSI300 three-model experiment dashboard."""
from __future__ import annotations
import csv, json, math
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "results/dashboards"
JSON_OUT = OUT / "csi300_three_model_experiment_dashboard_data.json"
HTML_OUT = OUT / "csi300_three_model_experiment_dashboard.html"
TRADE_CSV = ROOT / "results/cumulative_return_curves/csi300/csi300_three_model_cumulative_return_summary.csv"

SPECS = {
 "Kronos": {"stable_id":"Kronos","evaluation":"timesfm3/results/evaluation/Kronos","prediction":"experiments/csi300_aligned/models/zero_shot/predictions/by_date","model_id":"Kronos zero-shot","revision":None,"source_commit":None,"point_estimator":"sampled forecast path mean","device":None,"dtype":None,"inference":{"temperature":0.6,"top_p":0.9,"top_k":0,"sample_count":10,"batch_size":32,"oom_fallback_batch_size":16}},
 "Chronos-2": {"stable_id":"chronos2","evaluation":"chronos2/results/evaluation/chronos2","prediction":"chronos2/results/predictions/by_date","config":"chronos2/config.json","provenance":"chronos2/provenance.json","model_id":"amazon/chronos-2","revision":"29ec3766d36d6f73f0696f85560a422f50e8498c","source_commit":"4dbf163c2734c089cdf7da2b86fde48862ff9c6f","point_estimator":"q0.5","device":"cpu","dtype":"float32","inference":{"quantile":0.5,"sample_count":None}},
 "TimesFM 3": {"stable_id":"timesfm3","evaluation":"timesfm3/results/evaluation/timesfm3","prediction":"timesfm3/results/predictions/by_date","config":"timesfm3/config.json","provenance":"timesfm3/provenance.json","model_id":"google/timesfm-3.0-pytorch","revision":"43046b85ec22d584a13f8098c2ed39c889e129c2","source_commit":"e31dadd84cb26bd5153fde6687502b8312e918fb","point_estimator":"q0.5","device":"cpu","dtype":"float32","inference":{"quantile":0.5,"sample_count":None}},
}
POINT={"mae":"mae","rmse":"rmse","mase":"mase_vs_zero_return_persistence","oos_r2":"oos_r2_vs_zero_return"}
DIRECTION={"accuracy":"accuracy","balanced_accuracy":"balanced_accuracy","mcc":"mcc"}
RANKING={"path_ic":"pearson_ic_path_mean","path_rankic":"spearman_rankic_path_mean","quantile_spread":"q_high_minus_q_low_path_mean","top50_excess":"top50_excess_universe_path_mean","top50_bottom50":"top50_minus_bottom50_path_mean"}
TRADING={"net_cumulative_return":"net_cumulative_return","annualized_return_252":"annualized_net_return","maximum_drawdown":"maximum_drawdown","sharpe":"sharpe","sortino":"sortino","win_rate":"win_day_ratio","average_turnover":"turnover_mean","cumulative_cost":"cumulative_transaction_cost","trade_count":"trade_count","average_holding_days":"average_holding_days"}
GROUPS=[
 {"id":"point","title":"点预测指标","subtitle":"Path 口径 · 66,103 个股票—日期样本","metrics":list(POINT)},
 {"id":"direction","title":"方向预测指标","subtitle":"正收益定义为 return > 0；零收益视为负类","metrics":list(DIRECTION)},
 {"id":"ranking","title":"横截面排序指标","subtitle":"226 个交易日均值；Top50 列是预测评估指标，不是正式交易组合","metrics":list(RANKING)},
 {"id":"trading","title":"正式交易回测","subtitle":"统一重算：Top30 / Drop3 / 最短持有 5 日 / 单边换手成本 0.15%","metrics":list(TRADING)},
]
D={
 "mae":["MAE","decimal","min","mean(|预测收益 − 实际收益|)","平均绝对预测误差，越低越好。","mae","point.csv / Path"],
 "rmse":["RMSE","decimal","min","sqrt(mean((预测收益 − 实际收益)²))","对大误差更敏感，越低越好。","rmse","point.csv / Path"],
 "mase":["MASE","decimal","min","MAE / 零收益持久性基线 MAE","小于 1 表示优于基线，越低越好。","mase_vs_zero_return_persistence","point.csv / Path"],
 "oos_r2":["OOS R²","decimal","max","1 − SSE模型 / SSE零收益基线","样本外拟合优度；负值表示弱于基线，越高越好。","oos_r2_vs_zero_return","point.csv / Path"],
 "accuracy":["Accuracy","percent","max","正确方向样本数 / 全部有效样本数","总体方向判断准确率，越高越好。","accuracy","direction.csv / Path"],
 "balanced_accuracy":["Balanced Accuracy","percent","max","(Recall正类 + Recall负类) / 2","平衡正负类别后的准确率，越高越好。","balanced_accuracy","direction.csv / Path"],
 "mcc":["MCC","decimal","max","Matthews correlation coefficient","兼顾混淆矩阵四项的方向相关性，越高越好。","mcc","direction.csv / Path"],
 "path_ic":["Path IC","decimal","max","每日预测路径均值收益与实际路径均值收益的 Pearson 相关，再取均值","横截面线性排序能力，越高越好。","pearson_ic_path_mean.mean","ranking_summary.json"],
 "path_rankic":["Path RankIC","decimal","max","每日预测与实际路径均值收益的 Spearman 相关，再取均值","横截面秩排序能力，越高越好。","spearman_rankic_path_mean.mean","ranking_summary.json"],
 "quantile_spread":["分位数组合差","percent","max","最高预测分位组实际收益 − 最低预测分位组实际收益","检验预测分组收益单调性，越高越好。","q_high_minus_q_low_path_mean.mean","ranking_summary.json"],
 "top50_excess":["Top50 超额收益","percent","max","预测 Top50 实际收益 − 全股票池实际收益","预测评估指标而非正式回测，越高越好。","top50_excess_universe_path_mean.mean","ranking_summary.json"],
 "top50_bottom50":["Top50−Bottom50","percent","max","预测 Top50 实际收益 − 预测 Bottom50 实际收益","多空分层差，越高越好。","top50_minus_bottom50_path_mean.mean","ranking_summary.json"],
 "net_cumulative_return":["累计净收益","percent","max","∏(1 + 每日净收益) − 1","含交易成本的期末累计收益，越高越好。","net_cumulative_return","Top30 汇总 CSV"],
 "annualized_return_252":["252 日年化","percent","max","(1 + 累计净收益)^(252 / 交易日数) − 1","按 252 个交易日折算的年化净收益，越高越好。","annualized_net_return","Top30 汇总 CSV"],
 "maximum_drawdown":["最大回撤","percent","min_abs","min(组合净值 / 历史峰值 − 1)","净值从峰值到谷底的最大跌幅，绝对值越小越好。","maximum_drawdown","Top30 汇总 CSV"],
 "sharpe":["Sharpe","decimal","max","sqrt(252) × mean(日净收益) / std(日净收益)","单位总波动获得的收益，越高越好。","sharpe","Top30 汇总 CSV"],
 "sortino":["Sortino","decimal","max","sqrt(252) × mean(日净收益) / 下行标准差","单位下行风险获得的收益，越高越好。","sortino","Top30 汇总 CSV"],
 "win_rate":["胜率","percent","max","净收益为正的交易日数 / 全部交易日数","日度组合盈利比例，越高越好。","win_day_ratio","Top30 汇总 CSV"],
 "average_turnover":["平均换手","percent","min","每日单边权重换手率均值","组合日均调仓强度，越低通常越好。","turnover_mean","Top30 汇总 CSV"],
 "cumulative_cost":["累计成本","percent","min","Σ(每日单边权重换手率 × 0.15%)","累计交易成本率，越低越好。","cumulative_transaction_cost","Top30 汇总 CSV"],
 "trade_count":["交易笔数","integer","neutral","测试期建仓与换仓产生的交易计数","活动度描述指标，不进行优劣高亮。","trade_count","Top30 汇总 CSV"],
 "average_holding_days":["平均持有期","days","neutral","已完成持仓的持有交易日数均值","持仓节奏描述指标，不进行优劣高亮。","average_holding_days","Top30 汇总 CSV"],
}
DEFS={k:{"label":v[0],"format":v[1],"direction":v[2],"formula":v[3],"investment_meaning":v[4],"source_field":v[5],"source_kind":v[6]} for k,v in D.items()}

def rows(path):
 with path.open(encoding="utf-8-sig",newline="") as f:return list(csv.DictReader(f))
def one(items,key,value,path):
 found=[x for x in items if x.get(key)==value]
 if len(found)!=1:raise ValueError(f"{path}: expected one {key}={value}, got {len(found)}")
 return found[0]
def finite(value,context):
 x=float(value)
 if not math.isfinite(x):raise ValueError(f"non-finite {context}: {value}")
 return x

def build():
 trades=rows(TRADE_CSV)
 if len(trades)!=3 or {r["model"] for r in trades}!=set(SPECS):raise ValueError("Top30 summary model set mismatch")
 models=[]; sources={"formal_trade_summary":TRADE_CSV.relative_to(ROOT).as_posix(),"kronos_config":"experiments/csi300_aligned/reference/config.json","kronos_plan":"experiments/csi300_aligned/reference/experiment_plan.json"}
 for name,s in SPECS.items():
  base=ROOT/s["evaluation"]; pp=base/"point.csv"; dp=base/"direction.csv"; rp=base/"ranking_summary.json"
  p=one(rows(pp),"mode","Path",pp); d=one(rows(dp),"mode","Path",dp); rank=json.loads(rp.read_text(encoding="utf-8-sig")); t=one(trades,"model",name,TRADE_CSV)
  metrics={}
  for out,src in POINT.items():metrics[out]=finite(p[src],f"{name}.{out}")
  for out,src in DIRECTION.items():metrics[out]=finite(d[src],f"{name}.{out}")
  for out,src in RANKING.items():metrics[out]=finite(rank[src]["mean"],f"{name}.{out}")
  for out,src in TRADING.items():metrics[out]=finite(t[src],f"{name}.{out}")
  metrics["trade_count"]=int(metrics["trade_count"])
  if int(p["n"])!=66103 or int(d["n"])!=66103 or int(t["n_dates"])!=226:raise ValueError(f"sample count mismatch: {name}")
  if (int(t["top_k"]),int(t["drop_n"]),int(t["min_holding_days"]),finite(t["cost_rate"],"cost"))!=(30,3,5,.0015):raise ValueError(f"trading rule mismatch: {name}")
  ms={"point":pp.relative_to(ROOT).as_posix(),"direction":dp.relative_to(ROOT).as_posix(),"ranking":rp.relative_to(ROOT).as_posix(),"formal_trading":TRADE_CSV.relative_to(ROOT).as_posix(),"prediction_directory":s["prediction"]}
  if "config" in s:ms["config"]=s["config"]
  if "provenance" in s:ms["provenance"]=s["provenance"]
  for k,v in ms.items():sources[f'{s["stable_id"]}_{k}']=v
  models.append({"name":name,"stable_id":s["stable_id"],"model_id":s["model_id"],"revision":s["revision"],"source_commit":s["source_commit"],"point_estimator":s["point_estimator"],"device":s["device"],"dtype":s["dtype"],"prediction_directory":s["prediction"],"evaluation_directory":s["evaluation"],"inference":s["inference"],"metrics":metrics,"sources":ms})
 for mid,definition in DEFS.items():
  kind="formal_trading" if mid in TRADING else "point" if mid in POINT else "direction" if mid in DIRECTION else "ranking"
  definition["source_file"]={m["name"]:m["sources"][kind] for m in models}
 return {"schema_version":1,"dataset":"CSI300","title":"CSI300 三模型实验参数与指标看板","generated_at":datetime.now(timezone.utc).isoformat(),"common_parameters":{"train_end":"2024-12-15","validation_period":["2025-01-02","2025-06-14"],"test_period":["2025-07-01","2026-06-05"],"lookback":90,"prediction_length":10,"seed":100,"stock_date_samples":66103,"trading_dates":226,"target":"close","past_covariates":["open","high","low","volume"],"future_covariates":[],"cross_learning":False,"training":False,"signal":"predicted 10-day path mean return","realized_return":"actual_close_1 / current_close - 1"},"formal_trading_rules":{"selection":"Top30","weighting":"equal weight long-only","drop_n":3,"minimum_holding_days":5,"one_way_turnover_cost":.0015,"initial_capital_cny":1000000,"annualization_days":252},"bias_warning":"当前 CSI300 成分股回填历史区间，存在幸存者偏差和当前成分股前视偏差。","model_order":list(SPECS),"models":models,"metric_groups":GROUPS,"metric_definitions":DEFS,"sources":sources}

HTML='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CSI300 三模型实验参数与指标看板</title><style>
:root{--bg:#f4f7fb;--card:#fff;--ink:#172033;--muted:#667085;--line:#e3e9f2;--blue:#2563eb;--green-soft:#ecfdf3;--red:#b42318;--red-soft:#fff1f0;--shadow:0 10px 28px rgba(32,56,85,.08)}*{box-sizing:border-box}body{margin:0;background:linear-gradient(180deg,#eef4ff 0,#f7f9fc 260px,var(--bg) 100%);color:var(--ink);font:14px/1.55 Arial,"Microsoft YaHei",sans-serif}button{font:inherit}.wrap{max-width:1540px;margin:auto;padding:30px 26px 54px}.hero{display:flex;justify-content:space-between;gap:24px;align-items:flex-start;margin-bottom:18px}h1{font-size:30px;line-height:1.25;margin:0 0 7px}h2{font-size:19px;margin:0}h3{font-size:16px;margin:0}.muted{color:var(--muted)}.badge{display:inline-flex;border-radius:999px;background:#dbeafe;color:#1d4ed8;font-weight:700;padding:7px 12px;white-space:nowrap}.card{background:var(--card);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow);margin:16px 0;overflow:hidden}.card-head{display:flex;justify-content:space-between;gap:18px;align-items:start;padding:18px 20px 12px}.card-body{padding:0 20px 20px}.section-accent{border-left:4px solid var(--blue)}.params{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.param{background:#f8fafc;border:1px solid #e8edf4;border-radius:10px;padding:10px 12px;min-width:0}.param .k{font-size:12px;color:var(--muted);margin-bottom:2px}.param .v{font-weight:700;overflow-wrap:anywhere}.models{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.model-card{border:1px solid var(--line);border-top:4px solid var(--blue);border-radius:13px;padding:15px;background:#fff}.model-card:nth-child(2){border-top-color:#16a34a}.model-card:nth-child(3){border-top-color:#d97706}.model-title{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px}.model-title .id{font-size:11px;padding:3px 7px;border-radius:99px;background:#f1f5f9;color:#475569}.kv{display:grid;grid-template-columns:108px minmax(0,1fr);gap:6px 9px;margin:0;font-size:12.5px}.kv dt{color:var(--muted)}.kv dd{margin:0;overflow-wrap:anywhere}code{font-family:Consolas,monospace;font-size:.94em}.table-wrap{overflow:auto;border-top:1px solid var(--line)}table{width:100%;border-collapse:separate;border-spacing:0;min-width:840px}th,td{padding:11px 12px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap}thead th{position:sticky;top:0;background:#f8fafc;color:#475467;font-size:12px;z-index:1}th:first-child,td:first-child{position:sticky;left:0;text-align:left;background:#fff;z-index:2;font-weight:700}thead th:first-child{background:#f8fafc;z-index:3}tbody tr:last-child td{border-bottom:0}tbody tr:hover td,tbody tr:hover td:first-child{background:#f8fbff}.metric-btn{border:0;background:transparent;color:inherit;font-weight:700;padding:2px 0;border-bottom:1px dashed #98a2b3;cursor:pointer}.metric-btn:hover{color:var(--blue)}td.best{background:var(--green-soft)!important;color:#067647;font-weight:800}td.worst{background:var(--red-soft)!important;color:var(--red);font-weight:700}.legend{display:flex;gap:14px;align-items:center;flex-wrap:wrap;font-size:12px;color:var(--muted)}.dot{display:inline-block;width:9px;height:9px;border-radius:3px;margin-right:5px}.dot.best{background:#86efac}.dot.worst{background:#fda29b}.notice{border:1px solid #fed7aa;background:#fffbeb;color:#92400e;border-radius:12px;padding:12px 14px;margin:10px 0}.sources{columns:2;column-gap:28px;margin:0;padding-left:20px;font-size:12px;color:#475467}.sources li{break-inside:avoid;margin:4px 0;overflow-wrap:anywhere}.footer{text-align:center;color:var(--muted);font-size:12px;margin-top:22px}dialog{border:0;border-radius:16px;box-shadow:0 26px 70px rgba(15,23,42,.28);padding:0;width:min(620px,calc(100vw - 32px));color:var(--ink)}dialog::backdrop{background:rgba(15,23,42,.48)}.modal-head{display:flex;justify-content:space-between;gap:16px;padding:18px 20px;border-bottom:1px solid var(--line)}.modal-body{padding:18px 20px}.close{border:0;background:#f1f5f9;width:30px;height:30px;border-radius:8px;cursor:pointer;font-size:19px}.modal-grid{display:grid;grid-template-columns:110px 1fr;gap:9px 12px}.modal-grid .label{color:var(--muted)}.modal-grid div{overflow-wrap:anywhere}@media(max-width:980px){.params{grid-template-columns:repeat(2,minmax(0,1fr))}.models{grid-template-columns:1fr}.sources{columns:1}}@media(max-width:620px){.wrap{padding:20px 12px 38px}.hero{display:block}.badge{margin-top:12px}h1{font-size:24px}.params{grid-template-columns:1fr}.card-head{display:block}.legend{margin-top:8px}}
</style></head><body><main class="wrap"><header class="hero"><div><h1>CSI300 三模型实验参数与指标看板</h1><div class="muted">Kronos、Chronos-2 与 TimesFM 3 · 统一数据键、评估区间与正式交易规则</div></div><span class="badge">Top30 · Drop3 · 持有≥5日 · 成本0.15%</span></header><section class="card section-accent"><div class="card-head"><div><h2>公共实验参数</h2><div class="muted">单页只展示 CSI300 与三个固定模型；所有模型使用相同样本与评估口径。</div></div></div><div class="card-body"><div id="common-params" class="params"></div><div class="notice"><strong>偏差警告：</strong><span id="bias-warning"></span></div></div></section><section class="card"><div class="card-head"><div><h2>模型参数与资源映射</h2><div class="muted">使用稳定模型 ID 显式连接资源；Kronos 的采样参数不会应用到两个 CPU 基线。</div></div></div><div class="card-body"><div id="model-cards" class="models"></div></div></section><div id="metric-sections"></div><section class="card"><div class="card-head"><div><h2>数据来源</h2><div class="muted">外部 JSON 与本页内嵌数据由同一个对象生成，可离线审计。</div></div></div><div class="card-body"><ul id="sources" class="sources"></ul></div></section><div class="footer">所有数值均从模型自己的预测评估文件和统一 Top30 正式回测汇总读取。</div></main><dialog id="metric-modal"><div class="modal-head"><div><h3 id="modal-title"></h3><div class="muted">指标说明</div></div><button class="close" id="modal-close" aria-label="关闭">×</button></div><div class="modal-body" id="modal-body"></div></dialog><script id="dashboard-data" type="application/json">__DATA__</script><script>
"use strict";const DATA=JSON.parse(document.getElementById("dashboard-data").textContent);const $=id=>document.getElementById(id);const esc=value=>String(value??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));const fmt=(value,type)=>type==="percent"?(value*100).toFixed(2)+"%":type==="integer"?Math.round(value).toLocaleString("zh-CN"):type==="days"?value.toFixed(2)+" 日":value.toFixed(4);const c=DATA.common_parameters,r=DATA.formal_trading_rules;const items=[["数据集",DATA.dataset],["训练截止日",c.train_end],["验证区间",c.validation_period.join(" — ")],["测试区间",c.test_period.join(" — ")],["Lookback",c.lookback],["预测长度",c.prediction_length],["Seed",c.seed],["股票—日期样本",c.stock_date_samples.toLocaleString("zh-CN")],["交易日",c.trading_dates],["目标字段",c.target],["输入协变量",c.past_covariates.join(", ")],["未来协变量",c.future_covariates.length?c.future_covariates.join(", "):"无"],["预测信号",c.signal],["实际收益口径",c.realized_return],["正式选股",r.selection+" / Drop"+r.drop_n],["组合与成本","等权多头 · 单边 "+(r.one_way_turnover_cost*100).toFixed(2)+"%"],["最短持有",r.minimum_holding_days+" 个交易日"],["初始资金","¥"+r.initial_capital_cny.toLocaleString("zh-CN")],["年化天数",r.annualization_days],["训练 / 跨股票学习","否 / 否"]];$("common-params").innerHTML=items.map(([k,v])=>`<div class="param"><div class="k">${esc(k)}</div><div class="v">${esc(v)}</div></div>`).join("");$("bias-warning").textContent=DATA.bias_warning;$("model-cards").innerHTML=DATA.models.map(m=>{const infer=Object.entries(m.inference).filter(([,v])=>v!==null).map(([k,v])=>`${k}=${v}`).join(" · ");return `<article class="model-card" data-model="${esc(m.stable_id)}"><div class="model-title"><h3>${esc(m.name)}</h3><span class="id">${esc(m.stable_id)}</span></div><dl class="kv"><dt>Model ID</dt><dd><code>${esc(m.model_id)}</code></dd><dt>Revision</dt><dd><code>${esc(m.revision||"未提供（不伪造）")}</code></dd><dt>Source commit</dt><dd><code>${esc(m.source_commit||"—")}</code></dd><dt>点估计器</dt><dd>${esc(m.point_estimator)}</dd><dt>设备 / 精度</dt><dd>${esc(m.device&&m.dtype?m.device+" / "+m.dtype:"配置未记录")}</dd><dt>推理参数</dt><dd>${esc(infer)}</dd><dt>预测目录</dt><dd><code>${esc(m.prediction_directory)}</code></dd><dt>评估目录</dt><dd><code>${esc(m.evaluation_directory)}</code></dd></dl></article>`}).join("");function classes(id){const d=DATA.metric_definitions[id],vals=DATA.models.map(m=>m.metrics[id]);if(d.direction==="neutral")return new Map;const scores=vals.map(v=>d.direction==="min_abs"?Math.abs(v):v),best=d.direction==="max"?Math.max(...scores):Math.min(...scores),worst=d.direction==="max"?Math.min(...scores):Math.max(...scores);return new Map(scores.map((v,i)=>[DATA.models[i].stable_id,v===best?"best":v===worst?"worst":""]))}$("metric-sections").innerHTML=DATA.metric_groups.map(g=>{const maps=Object.fromEntries(g.metrics.map(id=>[id,classes(id)]));const heads=g.metrics.map(id=>`<th><button class="metric-btn" data-metric="${id}">${esc(DATA.metric_definitions[id].label)}</button></th>`).join("");const rows=DATA.models.map(m=>`<tr data-model-row="${esc(m.stable_id)}"><td>${esc(m.name)}</td>${g.metrics.map(id=>`<td data-metric-value="${id}" class="${maps[id].get(m.stable_id)||""}">${fmt(m.metrics[id],DATA.metric_definitions[id].format)}</td>`).join("")}</tr>`).join("");return `<section class="card metric-card" data-group="${g.id}"><div class="card-head"><div><h2>${esc(g.title)}</h2><div class="muted">${esc(g.subtitle)}</div></div><div class="legend"><span><i class="dot best"></i>最佳</span><span><i class="dot worst"></i>最差</span><span>点击表头查看定义</span></div></div><div class="table-wrap"><table><thead><tr><th>模型</th>${heads}</tr></thead><tbody>${rows}</tbody></table></div></section>`}).join("");$("sources").innerHTML=Object.entries(DATA.sources).map(([k,v])=>`<li><strong>${esc(k)}</strong>：<code>${esc(v)}</code></li>`).join("");const modal=$("metric-modal");function showMetric(id){const d=DATA.metric_definitions[id],dir={max:"越高越优",min:"越低越优",min_abs:"绝对值越低越优",neutral:"描述指标，不做优劣判断"}[d.direction],files=Object.entries(d.source_file).map(([m,p])=>`${esc(m)}：<code>${esc(p)}</code>`).join("<br>");$("modal-title").textContent=d.label;$("modal-body").innerHTML=`<div class="modal-grid"><div class="label">公式</div><div>${esc(d.formula)}</div><div class="label">优劣方向</div><div>${esc(dir)}</div><div class="label">投资含义</div><div>${esc(d.investment_meaning)}</div><div class="label">来源字段</div><div><code>${esc(d.source_field)}</code></div><div class="label">来源文件</div><div>${files}</div></div>`;modal.showModal()}document.addEventListener("click",e=>{const b=e.target.closest("[data-metric]");if(b)showMetric(b.dataset.metric)});$("modal-close").addEventListener("click",()=>modal.close());modal.addEventListener("click",e=>{if(e.target===modal)modal.close()});
</script></body></html>'''

