 data=build(); OUT.mkdir(parents=True,exist_ok=True); JSON_OUT.write_text(json.dumps(data,ensure_ascii=False,indent=2)+"\n",encoding="utf-8"); embedded=json.dumps(data,ensure_ascii=False,separators=(",",":")).replace("</","<\\/"); HTML_OUT.write_text(HTML.replace("__DATA__",embedded),encoding="utf-8"); print(JSON_OUT); print(HTML_OUT)
